---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Design tuner: Tweak a component by hand or let the agent tune it.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change design-tuner.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './design-tuner.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="design-tuner" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="dtx">
  <div class="dtx-prev"><div class="dtx-card">
    <span class="tag b dtx-tg">Pro</span>
    <div class="dtx-pr"><b class="num">$24</b><span class="muted">per editor, monthly</span></div>
    <div class="dtx-li"><span><svg class="i xs"><use href="#i-check"/></svg>Unlimited frames</span><span><svg class="i xs"><use href="#i-check"/></svg>Agent reviews</span><span><svg class="i xs"><use href="#i-check"/></svg>Shared tokens</span></div>
    <button class="pill accent dtx-cta">Start free trial</button>
  </div></div>
  <div class="dtx-insp panel">
    <div class="dtx-ih"><b>Pricing card</b><span class="muted dtx-st">Edited by you</span></div>
    <div class="dtx-rows"></div>
    <button class="pill primary sm dtx-go"><svg class="i xs"><use href="#i-wand"/></svg>Tune with agent</button>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './design-tuner.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Design tuner ---------- */
.dtx{display:grid;grid-template-columns:1fr 280px;gap:14px;align-items:stretch}
@media (max-width:720px){.dtx{grid-template-columns:1fr}}
@container (max-width:600px){.dtx{grid-template-columns:1fr}.dtx-prev{min-height:240px}}
.dtx-prev{border-radius:calc(18px * var(--dm-rk));background:var(--dm-chip);display:grid;place-items:center;padding:var(--dm-s-6);min-height:300px;min-width:0}
.dtx-card{--dm-rad:16px;--dm-pad:18px;--dm-gap:12px;--dm-sh:.08;width:min(250px,100%);background:var(--dm-surface);border-radius:var(--dm-rad);padding:var(--dm-pad);display:flex;flex-direction:column;gap:var(--dm-gap);box-shadow:0 1px 2px rgba(0,0,0,var(--dm-sh)),0 8px 24px rgba(0,0,0,calc(var(--dm-sh) * .8))}
.dtx-tg{align-self:flex-start}
.dtx-pr{display:flex;align-items:baseline;gap:6px}
.dtx-pr b{font-size:14px;font-weight:500;letter-spacing:-.02em}
.dtx-pr span{font-size:12px}
.dtx-li{display:flex;flex-direction:column;gap:6px;font-size:13px;color:var(--dm-fg2)}
.dtx-li span{display:flex;align-items:center;gap:7px}
.dtx-li svg{color:var(--dm-accent-fg,var(--dm-accent))}
.dtx-cta{width:100%;border-radius:calc(var(--dm-rad) * .6)}
.dtx-insp{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3);min-width:0}
.dtx-ih{display:flex;align-items:baseline;justify-content:space-between;font-size:13.5px}
.dtx-ih b{font-weight:500}
.dtx-st{font-size:12px}
.dtx-rows{display:flex;flex-direction:column;gap:10px}
.dtx-r{display:grid;grid-template-columns:62px 1fr 40px;align-items:center;gap:10px;font-size:12.5px;color:var(--dm-fg2)}
.dtx-r .v{text-align:right;color:var(--dm-fg);font-size:12px}
.dtx-r.hot .v{color:var(--dm-accent-fg,var(--dm-accent))}
.dtx-sl{position:relative;height:22px;display:flex;align-items:center;cursor:pointer;touch-action:none}
.dtx-sl::before{content:"";position:absolute;left:0;right:0;height:4px;border-radius:2px;background:var(--dm-line)}
.dtx-sl .f{position:absolute;left:0;height:4px;border-radius:2px;background:var(--dm-accent-mark,var(--dm-accent))}
.dtx-sl .k{position:absolute;width:14px;height:14px;margin-left:-7px;border-radius:50%;background:#fff;box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent),0 1px 3px rgba(0,0,0,.18);transition:transform .2s}
.dtx-sl.drag .k,.dtx-sl:focus-visible .k{transform:scale(1.15)}
@media (hover:hover) and (pointer:fine){.dtx-sl:hover .k{transform:scale(1.15)}}
.dtx-sl:focus-visible{outline-offset:4px}
.dtx-go{align-self:stretch;margin-top:auto}
.dtx-go.busy{pointer-events:none}
.dtx-note{font-size:12px;color:var(--dm-fg2);padding:var(--dm-s-2) 10px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-accent-bg);line-height:1.45}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, I, enter, html, swap, tween } from '../core/core.js';
DM.def('design-tuner', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{c\}/g, I('check','xs')).replace('{wand}', I('wand','xs'));
  const card = $('.dtx-card', r), rows = $('.dtx-rows', r), st = $('.dtx-st', r), go = $('.dtx-go', r);
  const P = [
    { k:'rad', n:'Radius', min:0, max:28, v:16, u:'px', t:20 },
    { k:'pad', n:'Padding', min:8, max:32, v:18, u:'px', t:24 },
    { k:'gap', n:'Spacing', min:4, max:24, v:12, u:'px', t:14 },
    { k:'sh', n:'Shadow', min:0, max:.2, v:.08, u:'', t:.05, f:2 }
  ];
  rows.innerHTML = P.map(p => `<div class="dtx-r" data-k="${p.k}"><span>${p.n}</span><div class="dtx-sl" role="slider" tabindex="0" aria-label="${p.n}" aria-valuemin="${p.min}" aria-valuemax="${p.max}"><span class="f"></span><span class="k"></span></div><span class="v num"></span></div>`).join('');
  function set(p, v){ p.v = Math.max(p.min, Math.min(p.max, v)); const pc = (p.v - p.min) / (p.max - p.min) * 100; const row = $(`[data-k="${p.k}"]`, rows);
    $('.f', row).style.width = pc + '%'; $('.k', row).style.left = pc + '%'; $('.v', row).textContent = p.f ? p.v.toFixed(p.f) : Math.round(p.v) + p.u;
    card.style.setProperty('--dm-' + p.k, p.f ? p.v : Math.round(p.v) + 'px'); $('.dtx-sl', row).setAttribute('aria-valuenow', p.f ? p.v.toFixed(p.f) : Math.round(p.v)); }
  P.forEach(p => {
    set(p, p.v); const sl = $(`[data-k="${p.k}"] .dtx-sl`, rows);
    const at = e => { const b = sl.getBoundingClientRect(); set(p, p.min + (p.max - p.min) * Math.max(0, Math.min(1, (e.clientX - b.left) / b.width))); };
    sl.onpointerdown = e => { sl.setPointerCapture(e.pointerId); sl.classList.add('drag'); at(e); swap(st, 'Edited by you'); sl.onpointermove = at; };
    sl.onpointerup = sl.onpointercancel = () => { sl.classList.remove('drag'); sl.onpointermove = null; };
    sl.onkeydown = e => { const k = { ArrowRight:1, ArrowUp:1, ArrowLeft:-1, ArrowDown:-1 }[e.key]; if (!k) return; e.preventDefault(); set(p, p.v + k * (p.f ? .01 : 1)); swap(st, 'Edited by you'); };
  });
  let note;
  go.onclick = () => c.run(async () => {
    go.classList.add('busy'); go.innerHTML = '<span class="think on"><i></i><i></i><i></i><i></i></span>Tuning'; swap(st, 'Agent is tuning'); if (note) note.remove();
    for (const p of P){ const row = $(`[data-k="${p.k}"]`, rows); row.classList.add('hot'); await tween(p.v, p.t, 650, x => set(p, x)); await c.wait(120); row.classList.remove('hot'); }
    note = html('<div class="dtx-note">Matched the 4px grid and your card tokens. Softer shadow so the CTA leads.</div>'); go.before(note); enter(note);
    go.classList.remove('busy'); go.innerHTML = I('wand','xs') + 'Tune again'; swap(st, 'Tuned by agent');
    P.forEach(p => { const o = p.t; p.t = p.k === 'rad' ? (o === 20 ? 12 : 20) : p.k === 'pad' ? (o === 24 ? 20 : 24) : p.k === 'gap' ? (o === 14 ? 10 : 14) : (o === .05 ? .1 : .05); });
  });
  // the preview lets the agent tune once on its own, unless you reach for a slider or the button first
  c.auto(1600, () => go.click());
});
